Transaction.Rules:
parm(EmpCod, &empnom , TempCod, &login , DorTipPlani, &Dornum, &Mode );

DORNum = &Dornum if update or delete;

noaccept(DORNum) ;

default(DorFecha, serverdate());
error('Ingrese Fecha despacho') if DorFecha = nullvalue(DorFecha);
//error('Ingrese Numero de Guia') if DorNguia = 0;
error('Ingrese Onservaciones') if DorObs1 = ' ';

call(PValPuerto , DorPuertoE, &SwPD) if after(DorPuertoE) and (insert or update);
error('Puerto de EMBARQUE debe ser NACIONAL') if &SwPD <> 1 and after(DorPuertoE) and (insert or update);

call(PTraeCor, EmpCod, 'DESFUMI' , DORNum, 0, 1,1) if after(DorNguia) and DorTipPlani = 2 and insert;
call(PTraeCor, EmpCod, 'DESMUES' , DORNum, 0, 1,1) if after(DorNguia) and DorTipPlani = 3 and insert;

DorFecCrea = serverdate() if insert;
DorLogcre  = &login if insert;

call(WDetDespacho , EmpCod , TempCod, &empnom , &Login, DorTipPlani, DORNum, &Mode ) if after(trn) and (insert or update );

CodeBlock.Source:
          &Folio = ' '

      endfor
//      if &Pas > 1
//         print total_folio
//      endif
endfor
